"""risk: returns, volatility and the report, over mdata's prices."""

import mdata
"""The PL-02 contract types: daily log returns and rolling volatility."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns: `dates` are the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]
"""PL-02: annualized rolling volatility of a prices CSV."""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path

from mdata import load_prices
from risk.annualize import annualize
from risk.returns import log_returns
from risk.types import VolSeries
from risk.vol import rolling_vol


def vol_series(
    path: str | Path, *, window: int = 20, tickers: Sequence[str] | None = None
) -> VolSeries:
    """Load the closes at `path`, take their returns and rolling vol, and annualize it."""
    prices = load_prices(path, tickers)
    returns = log_returns(prices)
    vol = rolling_vol(returns, window)
    return annualize(vol)
"""PL-02 step 4: annualized volatility."""

from __future__ import annotations

import dataclasses
import math

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """Scale each daily volatility by sqrt(periods_per_year) trading days; gaps stay None."""
    if vol.annualized:
        raise ValueError("vol is already annualized")
    factor = math.sqrt(periods_per_year)
    values = {
        ticker: tuple(None if v is None else v * factor for v in series)
        for ticker, series in vol.values.items()
    }
    return dataclasses.replace(vol, annualized=True, values=values)
"""PL-02 step 3: volatility from earlier returns."""

from __future__ import annotations

import statistics

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """Return each date's sample stdev of the `window` returns before it, None until they exist.

    A date's own return never enters its value (RISK-02).
    """
    if window < 2:
        raise ValueError(f"window must be at least 2, got {window}")
    values = {
        ticker: tuple(
            None if i < window else statistics.stdev(series[i - window : i])
            for i in range(len(series))
        )
        for ticker, series in returns.values.items()
    }
    return VolSeries(returns=returns, window=window, annualized=False, values=values)
"""PL-02 step 2: daily returns from aligned closes."""

from __future__ import annotations

import itertools
import math

from mdata import Prices
from risk.types import Returns


def log_returns(prices: Prices) -> Returns:
    """Return each ticker's log return r_t = ln(close_t / close_t-1), dated t."""
    if len(prices.dates) < 2:
        raise ValueError(f"need at least two dates for returns, got {len(prices.dates)}")
    values = {
        ticker: tuple(math.log(b / a) for a, b in itertools.pairwise(prices.closes[ticker]))
        for ticker in prices.tickers
    }
    return Returns(
        base_date=prices.dates[0],
        dates=prices.dates[1:],
        tickers=prices.tickers,
        values=values,
    )

"""Fake `mdata.load_prices`: serves the `mdata.Prices` sample and nothing else."""

from __future__ import annotations

import json
from collections.abc import Sequence
from pathlib import Path

from mdata import Prices

SAMPLE = Path(__file__).resolve().parent.parent / "mdata.Prices" / "sample.json"


def load_prices(path: str | Path, tickers: Sequence[str] | None = None) -> Prices:
    """Return the sample, narrowed to `tickers`; `path` is ignored.

    Raises `KeyError` for a requested ticker the sample doesn't hold, as the real step does.
    """
    del path
    payload = json.loads(SAMPLE.read_text())
    wanted = sorted(set(payload["tickers"] if tickers is None else tickers))
    missing = [t for t in wanted if t not in payload["closes"]]
    if missing:
        raise KeyError(", ".join(missing))
    return Prices(
        dates=tuple(payload["dates"]),
        tickers=tuple(wanted),
        closes={t: tuple(payload["closes"][t]) for t in wanted},
    )
